// Armar filas archivado — lo calificado de la semana → `outputs` (el histórico canónico, ADR-014).
// El Sheet murió en ADR-057: su reemplazo es el botón «Descargar CSV» de `/curar/historicos`. Desde D7 lee filas PLANAS de Postgres: se acabaron `fields`, los links y el
// cruce por record id — `proyecto_id`/`voz_id` son uuid y se cruzan contra el `id` del plan, que
// ES el uuid desde el paso 3 de D7 (contrato run-plan v2, ADR-048 §5: `fields.uuid` ya no viaja).
const _filas = (n) => { try { const a = $(n).all().map(i => i.json); return (a.length === 1 && Array.isArray(a[0])) ? a[0] : a; } catch (e) { return []; } };
const recs = _filas('Leer Candidatos calificados');
const run = $('Abrir run en el registro').first().json || {};
const run_id = run.id || null;

const _plan = $('Leer plan (fachada)').first().json || {};
const projMap = {}; (_plan.proyectos || []).forEach(r => { projMap[r.id] = (r.fields || {}).nombre || ''; });
const vozMap = {};  (_plan.voces || []).forEach(r => { vozMap[r.id] = (r.fields || {}).nombre || ''; });

const ESTADOS = { aprobado: 'aprobado', descartado: 'descartado' };
// (murió `_plataforma`: derivaba el `platform` de `source_items`, y esa columna se va en la `023`)

return recs.map(r => {
  const estado = ESTADOS[String(r.estado || '').toLowerCase()] || 'descartado';
  const proyecto = projMap[r.proyecto_id] || '';
  const voz = vozMap[r.voz_id] || '';
  const calificado_en = r.fecha_calificacion || new Date().toISOString();
  const output = {
    run_id,
    tipo: 'guion_reel',
    titulo: r.titulo || '(sin titulo)',
    contenido_o_link: r.script || '',
    estado,
    calificado_en,
    // El id del candidato en Postgres. Sigue siendo la clave de idempotencia de `outputs`
    // (UNIQUE(external_id), migración 005): un re-run no duplica el histórico.
    external_id: r.id,
    metadata: {
      proyecto, voz, referente: r.referente || '', url_referente: r.url_referente || '',
      idioma: r.idioma || '', views: r.views || 0, likes: r.likes || 0,
      seguidores: r.seguidores || 0, engagement: r.engagement || 0,
      heat_score: r.heat_score || 0, calificacion: r.calificacion || '',
      notas_equipo: r.notas_equipo || '', viral_por_tamano: !!r.viral_por_tamano,
      // La miniatura (ADR-072). Faltaba, y era una fuga: medido el 2026-08-21, 0 de las 172
      // filas guion_reel de outputs tenian thumbnail, asi que cada video archivado la perdia
      // para siempre. La URL firmada de IG vence en ~5 dias, pero /api/miniatura la copia a
      // Storage la primera vez que alguien la mira: guardarla da la chance de que eso pase.
      thumbnail_url: r.thumbnail_url || '',
      relevancia_score: (r.relevancia_score != null ? r.relevancia_score : null), relevancia_razon: r.relevancia_razon || ''
    }
  };
  return { json: { record_id: r.id, output } };
});

// El candidato archivado se borra: es cola de trabajo, y su historia ya quedó entera en `outputs`
// (ADR-014). El descarte, en cambio, NO se borra más (ADR-036) — nadie más guarda lo que se tiró.
//
// PostgREST borra por filtro, así que ya no hacen falta lotes de 10 ni una URL por lote: entra
// todo en un `id=in.(...)`. Se trocea igual, pero de a 200 y solo para no armar una URL gigante.
const ids = $('Armar filas archivado').all().map(i => i.json.record_id).filter(Boolean);
const base = $('Config').first().json.supabase_url + '/rest/v1/candidatos?id=in.';
const out = [];
for (let i = 0; i < ids.length; i += 200) {
  out.push({ json: { url: base + '(' + ids.slice(i, i + 200).join(',') + ')' } });
}
console.log('[Archivado] borrando ' + ids.length + ' candidatos archivados');
return out; // [] si no hay nada: el DELETE no corre

// Destilar criterios (ADR-022 / M2): por proyecto, Haiku resume los calificados de la semana en
// patrones (lo que SI / lo que NO) priorizando los 🔥 como ejemplos positivos (fallback aprobados);
// la MISMA llamada evalua los criterios manuales y deja una advertencia de forma (lint). Escribe
// criterios_aprendidos + advertencia_criterios en Proyectos — NUNCA pisa criterios_relevancia manual.
// Fail-soft: cuelga de Cerrar run (onError:continue); si Haiku falla, ese proyecto se salta.
const KEY = '<ANTHROPIC_API_KEY>';
const MIN = Number($('Config').first().json.min_muestra_destilar || 4); // no destila con < MIN calificados/proyecto
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
let proyectos = [];
try { proyectos = ($('Leer plan (fachada)').first().json.proyectos || []); } catch (e) {}
let voces = [];
try { voces = ($('Leer plan (fachada)').first().json.voces || []); } catch (e) {}
let califs = [];
// D7: filas PLANAS de Postgres (antes: {records:[{fields}]} de Airtable).
try { const _a = $('Leer Candidatos calificados').all().map(i => i.json); califs = (_a.length === 1 && Array.isArray(_a[0])) ? _a[0] : _a; } catch (e) {}

const vozCrit = {};
voces.forEach(v => { vozCrit[v.id] = ((v.fields || {}).criterios_relevancia || '').toString().trim(); });
const projMeta = {};
proyectos.forEach(r => { const f = r.fields || {}; const vid = Array.isArray(f.voz_default) && f.voz_default[0] ? f.voz_default[0] : null; projMeta[r.id] = { nombre: f.nombre || r.id, criterios: (f.criterios_relevancia || '').toString().trim(), voz_criterios: vid ? (vozCrit[vid] || '') : '' }; });

const byProj = {};
for (const r of califs) {

  const pid = r.proyecto_id || '';
  if (!pid || !projMeta[pid]) continue;
  (byProj[pid] = byProj[pid] || []).push(r);
}

const _snip = (f) => ({ titulo: String(f.titulo || '').slice(0, 80), texto: String(f.script || '').replace(/\s+/g, ' ').trim().slice(0, 500) });
const recs = [];
let first = true;
for (const pid in byProj) {
  const arr = byProj[pid];
  if (arr.length < MIN) continue; // poca senal: no aprende de una semana chica (mitiga la (-) del ADR)
  const meta = projMeta[pid];
  const fuego = arr.filter(f => String(f.calificacion || '').indexOf('🔥') >= 0);
  const aprob = arr.filter(f => String(f.estado || '').toLowerCase() === 'aprobado');
  const desc = arr.filter(f => String(f.estado || '').toLowerCase() === 'descartado');
  const positivos = (fuego.length ? fuego : aprob).slice(0, 6).map(_snip); // 🔥 prioriza; fallback aprobados
  const negativos = desc.slice(0, 6).map(_snip);
  if (!positivos.length && !negativos.length) continue;
  const sys = 'Sos un analista que destila criterios de curacion de contenido para un jurado automatico. Te doy los criterios manuales de un proyecto (TEMA) y su VOZ, y ejemplos reales que el equipo APROBO (los mejores marcados) y DESCARTO. Devolve UNICAMENTE JSON {"criterios_aprendidos":"...","advertencia":"..."}. criterios_aprendidos: 2-3 patrones concretos en espanol de que SI y que NO hace relevante un video para este proyecto, con mini-ejemplos, redactados como guia para el jurado. advertencia: evalua los criterios manuales - permiten RECHAZAR (tienen lista negativa)? son especificos o vagos? la voz es coherente con el tema? Si estan sanos, devolve "". Se breve.';
  const usr = 'TEMA: ' + meta.nombre + '\nCRITERIOS MANUALES (tema):\n' + (meta.criterios || '(vacio)') + '\nCRITERIOS DE VOZ:\n' + (meta.voz_criterios || '(vacio)') + '\n\nAPROBADOS' + (fuego.length ? ' (los 🔥 son ideales)' : '') + ':\n' + JSON.stringify(positivos) + '\n\nDESCARTADOS:\n' + JSON.stringify(negativos);
  try {
    if (!first) await sleep(1000); first = false;
    const resp = await this.helpers.httpRequest({
      method: 'POST', url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model: 'claude-haiku-4-5', max_tokens: 1000, system: sys, messages: [{ role: 'user', content: usr }] },
      json: true, timeout: 60000
    });
    let txt = '';
    try { txt = (resp.content && resp.content[0] && resp.content[0].text) || ''; } catch (e) {}
    const mm = String(txt).match(/\{[\s\S]*\}/);
    if (!mm) continue;
    const parsed = JSON.parse(mm[0]);
    const fields = {};
    if (parsed.criterios_aprendidos) fields.criterios_aprendidos = String(parsed.criterios_aprendidos).slice(0, 2000);
    fields.advertencia_criterios = parsed.advertencia ? String(parsed.advertencia).slice(0, 1000) : '';
    // D7: se PATCHea `app.proyectos` por uuid, uno por proyecto. Con esto los criterios
    // destilados y su escritor vuelven al mismo lugar, y **muere ADR-033** — la regla del
    // "un dueño por CAMPO" existía solo mientras este nodo escribiera en Airtable.
    // `pid` YA es el uuid: viene de `candidatos.proyecto_id` y matchea el `id` del plan (v2).
    if (fields.criterios_aprendidos || fields.advertencia_criterios) recs.push({ proyecto_id: pid, campos: fields });
  } catch (e) { /* fail-soft por proyecto */ }
}
console.log('[Destilar] proyectos actualizados: ' + recs.length);
return recs.map(r => ({ json: r })); // [] si nada: el PATCH no corre
